  task automatic apply_reset(input integer cycles);
    begin
      @(negedge clk);
      rst_n = 1'b0;
      repeat (cycles) @(posedge clk);
      @(negedge clk);
      rst_n = 1'b1;
      @(posedge clk);
    end
  endtask

  function automatic real avg_cycles(
    input integer sum_cycles,
    input integer count
  );
    begin
      avg_cycles = (count > 0) ? ((1.0 * sum_cycles) / count) : 0.0;
    end
  endfunction

  function automatic real delta_cycles(
    input integer lhs_sum,
    input integer lhs_count,
    input integer rhs_sum,
    input integer rhs_count
  );
    begin
      delta_cycles = avg_cycles(lhs_sum, lhs_count) - avg_cycles(rhs_sum, rhs_count);
    end
  endfunction

  function automatic integer classify_read_tier(
    input logic hit,
    input integer l1_hit_before,
    input integer l2_demand_hit_before,
    input integer l2_demand_miss_before,
    input integer l2_vb_hit_before,
    input integer l2_gf_hit_before
  );
    integer l1_hit_delta;
    integer l2_demand_hit_delta;
    integer l2_demand_miss_delta;
    integer l2_vb_hit_delta;
    integer l2_gf_hit_delta;
    begin
      l1_hit_delta = dut.u_mcu.u_ex.stat_l1_hit_cnt - l1_hit_before;
      l2_demand_hit_delta = dut.u_mcu.stat_l2_demand_hit_cnt - l2_demand_hit_before;
      l2_demand_miss_delta = dut.u_mcu.stat_l2_demand_miss_cnt - l2_demand_miss_before;
      l2_vb_hit_delta = dut.u_mcu.u_l2.stat_l2_vb_read_hit_cnt - l2_vb_hit_before;
      l2_gf_hit_delta = dut.u_mcu.u_l2.stat_l2_group_fetch_useful_cnt - l2_gf_hit_before;

      if (l1_hit_delta > 0) begin
        classify_read_tier = LAT_TIER_L1;
      end else if (l2_demand_hit_delta > 0) begin
        if (l2_gf_hit_delta > 0) begin
          classify_read_tier = LAT_TIER_GF;
        end else if (l2_vb_hit_delta > 0) begin
          classify_read_tier = LAT_TIER_CVR;
        end else begin
          classify_read_tier = LAT_TIER_L2;
        end
      end else if ((l2_demand_miss_delta > 0) || !hit) begin
        classify_read_tier = LAT_TIER_L3;
      end else begin
        classify_read_tier = LAT_TIER_UNCLASSIFIED;
      end
    end
  endfunction

  task automatic record_access(
    input kcmu_op_t op,
    input logic hit,
    input integer latency_cycles,
    input integer read_tier
  );
    begin
      total_ops = total_ops + 1;
      total_latency_cycles = total_latency_cycles + latency_cycles;
      if (latency_cycles <= 0) begin
        latency_hist_0 = latency_hist_0 + 1;
      end else if (latency_cycles == 1) begin
        latency_hist_1 = latency_hist_1 + 1;
      end else if (latency_cycles == 2) begin
        latency_hist_2 = latency_hist_2 + 1;
      end else if (latency_cycles == 3) begin
        latency_hist_3 = latency_hist_3 + 1;
      end else if (latency_cycles == 4) begin
        latency_hist_4 = latency_hist_4 + 1;
      end else if (latency_cycles <= 7) begin
        latency_hist_5_7 = latency_hist_5_7 + 1;
      end else if (latency_cycles <= 15) begin
        latency_hist_8_15 = latency_hist_8_15 + 1;
      end else if (latency_cycles <= 31) begin
        latency_hist_16_31 = latency_hist_16_31 + 1;
      end else if (latency_cycles <= 63) begin
        latency_hist_32_63 = latency_hist_32_63 + 1;
      end else begin
        latency_hist_64p = latency_hist_64p + 1;
      end
      if (latency_cycles > max_latency_cycles) begin
        max_latency_cycles = latency_cycles;
      end
      if (op == KCMU_OP_RD) begin
        total_reads = total_reads + 1;
        total_read_latency_cycles = total_read_latency_cycles + latency_cycles;
        case (read_tier)
          LAT_TIER_L1: begin
            total_read_l1_cnt = total_read_l1_cnt + 1;
            total_read_l1_latency_cycles = total_read_l1_latency_cycles + latency_cycles;
          end
          LAT_TIER_L2: begin
            total_read_l2_cnt = total_read_l2_cnt + 1;
            total_read_l2_latency_cycles = total_read_l2_latency_cycles + latency_cycles;
          end
          LAT_TIER_CVR: begin
            total_read_cvr_cnt = total_read_cvr_cnt + 1;
            total_read_cvr_latency_cycles = total_read_cvr_latency_cycles + latency_cycles;
          end
          LAT_TIER_GF: begin
            total_read_gf_cnt = total_read_gf_cnt + 1;
            total_read_gf_latency_cycles = total_read_gf_latency_cycles + latency_cycles;
          end
          LAT_TIER_L3: begin
            total_read_l3_cnt = total_read_l3_cnt + 1;
            total_read_l3_latency_cycles = total_read_l3_latency_cycles + latency_cycles;
          end
          default: begin
            total_read_unclassified_cnt = total_read_unclassified_cnt + 1;
            total_read_unclassified_latency_cycles = total_read_unclassified_latency_cycles + latency_cycles;
          end
        endcase
        if (dut.u_mcu.last_read_backend_critical_hot)
          total_backend_critical_hot_reads = total_backend_critical_hot_reads + 1;
        if (dut.u_mcu.last_read_h2o_search_l2_miss_heavy)
          total_kiloscore_heavy_reads = total_kiloscore_heavy_reads + 1;
        if (dut.u_mcu.last_read_h2o_search_meta_guard)
          total_kiloscore_meta_reads = total_kiloscore_meta_reads + 1;
        if (dut.u_mcu.last_read_h2o_search_floor_guard)
          total_kiloscore_floor_reads = total_kiloscore_floor_reads + 1;
        if (dut.u_mcu.last_read_h2o_search_retention_guard)
          total_kiloscore_retention_reads = total_kiloscore_retention_reads + 1;
        if (dut.u_mcu.last_read_backend_critical_warm)
          total_backend_critical_warm_reads = total_backend_critical_warm_reads + 1;
        if (dut.u_mcu.last_read_backend_critical_qos_boost)
          total_backend_critical_qos_boost_reads = total_backend_critical_qos_boost_reads + 1;
        if (dut.u_mcu.last_read_backend_critical_fill_effect)
          total_backend_critical_fill_effect_reads = total_backend_critical_fill_effect_reads + 1;
        if (dut.u_mcu.last_read_backend_critical_protect_effect)
          total_backend_critical_protect_effect_reads = total_backend_critical_protect_effect_reads + 1;
        if (dut.u_mcu.last_read_backend_critical_prio_raise)
          total_backend_critical_prio_raise_reads = total_backend_critical_prio_raise_reads + 1;
        if (dut.u_mcu.last_read_backend_critical_cross3)
          total_backend_critical_cross3_reads = total_backend_critical_cross3_reads + 1;
        if (dut.u_mcu.last_read_backend_critical_cross4)
          total_backend_critical_cross4_reads = total_backend_critical_cross4_reads + 1;
        if (dut.u_mcu.last_read_backend_critical_cross5)
          total_backend_critical_cross5_reads = total_backend_critical_cross5_reads + 1;
        if (dut.u_mcu.last_read_backend_critical_fill_mask_sched)
          total_backend_critical_fill_mask_sched_reads = total_backend_critical_fill_mask_sched_reads + 1;
        if (dut.u_mcu.last_read_backend_critical_fill_mask_prio)
          total_backend_critical_fill_mask_prio_reads = total_backend_critical_fill_mask_prio_reads + 1;
        if (dut.u_mcu.last_read_backend_critical_fill_mask_budget)
          total_backend_critical_fill_mask_budget_reads = total_backend_critical_fill_mask_budget_reads + 1;
        if (dut.u_mcu.last_read_backend_critical_protect_mask_sched)
          total_backend_critical_protect_mask_sched_reads = total_backend_critical_protect_mask_sched_reads + 1;
        if (dut.u_mcu.last_read_backend_critical_protect_mask_guard)
          total_backend_critical_protect_mask_guard_reads = total_backend_critical_protect_mask_guard_reads + 1;
        if (dut.u_mcu.last_read_backend_critical_protect_mask_prio)
          total_backend_critical_protect_mask_prio_reads = total_backend_critical_protect_mask_prio_reads + 1;
        if (dut.u_mcu.last_read_h2o_admission_hot)
          total_h2o_admission_hot_reads = total_h2o_admission_hot_reads + 1;
        if (dut.u_mcu.last_read_h2o_admission_warm)
          total_h2o_admission_warm_reads = total_h2o_admission_warm_reads + 1;
        if (dut.u_mcu.last_read_h2o_admission_qos_boost)
          total_h2o_admission_qos_boost_reads = total_h2o_admission_qos_boost_reads + 1;
        if (dut.u_mcu.last_read_h2o_admission_fill_effect)
          total_h2o_admission_fill_effect_reads = total_h2o_admission_fill_effect_reads + 1;
        if (dut.u_mcu.last_read_h2o_admission_protect_effect)
          total_h2o_admission_protect_effect_reads = total_h2o_admission_protect_effect_reads + 1;
        if (dut.u_mcu.last_read_h2o_admission_fill_mask_sched)
          total_h2o_admission_fill_mask_sched_reads = total_h2o_admission_fill_mask_sched_reads + 1;
        if (dut.u_mcu.last_read_h2o_admission_fill_mask_prio)
          total_h2o_admission_fill_mask_prio_reads = total_h2o_admission_fill_mask_prio_reads + 1;
        if (dut.u_mcu.last_read_h2o_admission_fill_mask_budget)
          total_h2o_admission_fill_mask_budget_reads = total_h2o_admission_fill_mask_budget_reads + 1;
        if (dut.u_mcu.last_read_h2o_admission_protect_mask_sched)
          total_h2o_admission_protect_mask_sched_reads = total_h2o_admission_protect_mask_sched_reads + 1;
        if (dut.u_mcu.last_read_h2o_admission_protect_mask_guard)
          total_h2o_admission_protect_mask_guard_reads = total_h2o_admission_protect_mask_guard_reads + 1;
        if (dut.u_mcu.last_read_h2o_admission_protect_mask_prio)
          total_h2o_admission_protect_mask_prio_reads = total_h2o_admission_protect_mask_prio_reads + 1;
        if (dut.u_mcu.last_read_service_fill_rescue)
          total_service_fill_rescue_reads = total_service_fill_rescue_reads + 1;
        if (dut.u_mcu.last_read_service_issue_utility) begin
          total_service_issue_utility_reads = total_service_issue_utility_reads + 1;
          if (dut.u_mcu.last_read_service_issue_score_ge)
            total_service_issue_score_raw_reads = total_service_issue_score_raw_reads + 1;
          if (dut.u_mcu.last_read_service_issue_prio_ge)
            total_service_issue_prio_raw_reads = total_service_issue_prio_raw_reads + 1;
          if (dut.u_mcu.last_read_service_issue_launch_gate)
            total_service_issue_launch_gate_raw_reads = total_service_issue_launch_gate_raw_reads + 1;
          if (dut.u_mcu.last_read_service_issue_fillprotect)
            total_service_issue_fillprotect_raw_reads = total_service_issue_fillprotect_raw_reads + 1;
          if (dut.u_mcu.last_read_service_issue_write_pressure) begin
            total_service_issue_write_pressure_reads = total_service_issue_write_pressure_reads + 1;
            if (dut.u_mcu.last_read_service_issue_no_compress) begin
              total_service_issue_nocompress_reads = total_service_issue_nocompress_reads + 1;
              if (dut.u_mcu.last_read_service_issue_score_ge) begin
                total_service_issue_score_reads = total_service_issue_score_reads + 1;
                if (dut.u_mcu.last_read_service_issue_prio_ge) begin
                  total_service_issue_prio_reads = total_service_issue_prio_reads + 1;
                  if (dut.u_mcu.last_read_service_issue_launch_gate)
                    total_service_issue_launch_gate_reads = total_service_issue_launch_gate_reads + 1;
                  if (dut.u_mcu.last_read_service_issue_fillprotect)
                    total_service_issue_fillprotect_reads = total_service_issue_fillprotect_reads + 1;
                end
              end
            end
          end
        end
        if (dut.u_mcu.last_read_service_issue_boost)
          total_service_issue_boost_reads = total_service_issue_boost_reads + 1;
        if (dut.u_mcu.last_read_service_issue_sched_bridge)
          total_service_issue_sched_bridge_reads = total_service_issue_sched_bridge_reads + 1;
        if (dut.u_mcu.last_read_backend_demand_bridge)
          total_backend_demand_bridge_reads = total_backend_demand_bridge_reads + 1;
        if (dut.u_mcu.last_read_backend_demand_bridge_candidate)
          total_backend_demand_bridge_candidate_reads = total_backend_demand_bridge_candidate_reads + 1;
        if (dut.u_mcu.last_read_backend_demand_bridge_window)
          total_backend_demand_bridge_window_reads = total_backend_demand_bridge_window_reads + 1;
        if (dut.u_mcu.last_read_backend_demand_bridge_prio)
          total_backend_demand_bridge_prio_reads = total_backend_demand_bridge_prio_reads + 1;
        if (dut.u_mcu.last_read_backend_demand_bridge_hh)
          total_backend_demand_bridge_hh_reads = total_backend_demand_bridge_hh_reads + 1;
        if (dut.u_mcu.last_read_backend_demand_bridge_query)
          total_backend_demand_bridge_query_reads = total_backend_demand_bridge_query_reads + 1;
      end else if (op == KCMU_OP_WR) begin
        total_writes = total_writes + 1;
        total_write_latency_cycles = total_write_latency_cycles + latency_cycles;
      end
      if (hit) total_hits = total_hits + 1;
      else     total_misses = total_misses + 1;
    end
  endtask

  function automatic logic read_value_match(
    input logic [DATA_W-1:0] exp_data,
    input logic [DATA_W-1:0] got_data,
    input logic approx_flag
  );
    integer bi;
    integer diff;
    integer expb;
    integer gotb;
    begin
      if (!L2_LOSSY_COMPRESS_EN || !approx_flag) begin
        read_value_match = (got_data === exp_data);
      end else begin
        read_value_match = 1'b1;
        for (bi = 0; bi < BYTE_W; bi = bi + 1) begin
          expb = exp_data[bi*8 +: 8];
          gotb = got_data[bi*8 +: 8];
          if (expb >= gotb) diff = expb - gotb;
          else              diff = gotb - expb;
          if (diff > LOSSY_BYTE_EPS) begin
            read_value_match = 1'b0;
          end
        end
      end
    end
  endfunction

  function automatic logic [DATA_W-1:0] desc_generated_wdata(
    input logic [ADDR_W-1:0]     addr_i,
    input logic [7:0]            beat_i,
    input logic [KCMU_SEQ_W-1:0] seq_id_i,
    input logic [SCORE_W-1:0]    score_i
  );
    logic [DATA_W-1:0] tmp;
    begin
      tmp = {DATA_W{1'b0}};
      if (DATA_W >= 8)  tmp[7:0] = addr_i[7:0];
      if (DATA_W >= 16) tmp[15:8] = beat_i;
      if (DATA_W >= 24) tmp[23:16] = seq_id_i[7:0];
      if (DATA_W >= 32) tmp[31:24] = score_i[7:0];
      desc_generated_wdata = tmp;
    end
  endfunction

  task automatic do_cmd_with_full_meta(
    input  kcmu_op_t op,
    input  logic [ADDR_W-1:0] addr,
    input  logic [DATA_W-1:0] wdata,
    input  logic meta_valid_i,
    input  logic [KCMU_SEQ_W-1:0] seq_id_i,
    input  kcmu_phase_t phase_i,
    input  kcmu_kv_kind_t kv_kind_i,
    input  logic [2:0] layer_i,
    input  logic [1:0] head_i,
    input  logic [11:0] token_i,
    input  logic [2:0] prio_i,
    output logic [DATA_W-1:0] rdata,
    output logic hit,
    output integer latency_cycles,
    output integer read_tier
  );
    integer wait_cnt;
    integer l1_hit_before;
    integer l2_demand_hit_before;
    integer l2_demand_miss_before;
    integer l2_vb_hit_before;
    integer l2_gf_hit_before;
    begin
      latency_cycles = 0;
      read_tier = LAT_TIER_NONE;
      l1_hit_before = dut.u_mcu.u_ex.stat_l1_hit_cnt;
      l2_demand_hit_before = dut.u_mcu.stat_l2_demand_hit_cnt;
      l2_demand_miss_before = dut.u_mcu.stat_l2_demand_miss_cnt;
      l2_vb_hit_before = dut.u_mcu.u_l2.stat_l2_vb_read_hit_cnt;
      l2_gf_hit_before = dut.u_mcu.u_l2.stat_l2_group_fetch_useful_cnt;

      @(negedge clk);
      trace_valid = 1'b1;
      trace_op = op;
      trace_addr = addr;
      trace_wdata = wdata;
      trace_meta_valid = meta_valid_i;
      trace_seq_id = seq_id_i;
      trace_phase = phase_i;
      trace_kv_kind = kv_kind_i;
      trace_layer = layer_i;
      trace_head = head_i;
      trace_token = token_i;
      trace_prio = prio_i;

      wait_cnt = 0;
      while (!trace_ready) begin
        @(posedge clk);
        wait_cnt = wait_cnt + 1;
        if (wait_cnt > READY_TIMEOUT) begin
          $fatal(1, "trace_ready timeout, op=%0d addr=%0d", op, addr);
        end
      end

      @(negedge clk);
      trace_valid = 1'b0;
      trace_op = KCMU_OP_NOP;
      trace_addr = '0;
      trace_wdata = '0;
      trace_meta_valid = 1'b0;
      trace_seq_id = {KCMU_SEQ_W{1'b0}};
      trace_phase = KCMU_PHASE_PREFILL;
      trace_kv_kind = KCMU_KV_KIND_K;
      trace_layer = 3'd0;
      trace_head = 2'd0;
      trace_token = 12'd0;
      trace_prio = 3'd0;

      wait_cnt = 0;
      while (!resp_valid) begin
        @(posedge clk);
        wait_cnt = wait_cnt + 1;
        if (wait_cnt > RESP_TIMEOUT) begin
          $fatal(1, "resp_valid timeout, op=%0d addr=%0d", op, addr);
        end
      end

      rdata = resp_rdata;
      hit = resp_hit;
      last_resp_approx = resp_approx;
      latency_cycles = wait_cnt;
      if (op == KCMU_OP_RD) begin
        read_tier = classify_read_tier(
          resp_hit,
          l1_hit_before,
          l2_demand_hit_before,
          l2_demand_miss_before,
          l2_vb_hit_before,
          l2_gf_hit_before
        );
      end
      @(posedge clk);
    end
  endtask

  task automatic do_descriptor(
    input  kcmu_op_t              op_i,
    input  logic [ADDR_W-1:0]     base_addr_i,
    input  logic [7:0]            len_i,
    input  logic [SCORE_W-1:0]    score_i,
    input  logic [KCMU_SEQ_W-1:0] seq_id_i,
    input  kcmu_phase_t           phase_i,
    input  kcmu_kv_kind_t         kv_kind_i,
    input  logic                  attn_valid_i,
    input  logic [SCORE_W-1:0]    attn_score_i,
    input  logic [KCMU_ATTN_RANK_W-1:0] recent_rank_i,
    input  logic [KCMU_TOKEN_BLOCK_W-1:0] token_block_id_i,
    input  logic [KCMU_ATTN_EPOCH_W-1:0] attn_epoch_i
  );
    integer beat_idx;
    integer wait_cnt;
    integer lat_l;
    integer read_tier_l;
    integer l1_hit_before_l;
    integer l2_demand_hit_before_l;
    integer l2_demand_miss_before_l;
    integer l2_vb_hit_before_l;
    integer l2_gf_hit_before_l;
    logic [ADDR_W-1:0] addr_l;
    logic [DATA_W-1:0] exp_data_l;
    begin
      if (len_i == 8'd0) begin
        $fatal(1, "descriptor length must be non-zero");
      end

      @(negedge clk);
      trace_desc_valid <= 1'b1;
      trace_desc_op <= op_i;
      trace_desc_base_addr <= base_addr_i;
      trace_desc_len <= len_i;
      trace_desc_score <= score_i;
      trace_desc_seq_id <= seq_id_i;
      trace_desc_phase <= phase_i;
      trace_desc_kv_kind <= kv_kind_i;
      trace_desc_attn_valid <= attn_valid_i;
      trace_desc_attn_score <= attn_score_i;
      trace_desc_recent_rank <= recent_rank_i;
      trace_desc_token_block_id <= token_block_id_i;
      trace_desc_attn_epoch <= attn_epoch_i;
      trace_desc_head_budget_class <= UTILITY_USE_HEAD_FIELD ? desc_head_budget_class_cfg : '0;
      trace_desc_query_relevance <= UTILITY_USE_QUERY_FIELD ? desc_query_relevance_cfg : '0;
      trace_desc_compression_risk <= UTILITY_USE_COMPRESSION_FIELD ? desc_compression_risk_cfg : '0;
      trace_desc_spill_cost <= UTILITY_USE_SPILL_FIELD ? desc_spill_cost_cfg : '0;
      trace_desc_service_criticality <= UTILITY_USE_SERVICE_FIELD ? desc_service_criticality_cfg : '0;
      trace_desc_policy_select_s5 <= desc_policy_select_s5_cfg;
      trace_desc_temporal_persist_class <= desc_temporal_persist_class_cfg;
      trace_desc_reuse_distance_class <= desc_reuse_distance_class_cfg;
      trace_desc_query_structure_class <= desc_query_structure_class_cfg;
      trace_desc_sched_urgency_hint <= desc_sched_urgency_hint_cfg;
      trace_desc_sig_valid <= desc_sig_valid_cfg;
      trace_desc_query_sig <= desc_query_sig_cfg;
      trace_desc_key_sig <= desc_key_sig_cfg;
      trace_desc_prefix_class <= desc_prefix_class_cfg;
      trace_desc_router_class <= desc_router_class_cfg;

      wait_cnt = 0;
      while (!trace_desc_ready) begin
        @(posedge clk);
        wait_cnt = wait_cnt + 1;
        if (wait_cnt > READY_TIMEOUT) begin
          $fatal(1, "trace_desc_ready timeout, op=%0d base=%0d len=%0d", op_i, base_addr_i, len_i);
        end
      end

      @(negedge clk);
      trace_desc_valid <= 1'b0;
      trace_desc_op <= KCMU_OP_NOP;
      trace_desc_base_addr <= '0;
      trace_desc_len <= 8'd0;
      trace_desc_score <= '0;
      trace_desc_seq_id <= {KCMU_SEQ_W{1'b0}};
      trace_desc_phase <= KCMU_PHASE_PREFILL;
      trace_desc_kv_kind <= KCMU_KV_KIND_K;
      trace_desc_attn_valid <= 1'b0;
      trace_desc_attn_score <= '0;
      trace_desc_recent_rank <= '0;
      trace_desc_token_block_id <= '0;
      trace_desc_attn_epoch <= '0;
      trace_desc_head_budget_class <= '0;
      trace_desc_query_relevance <= '0;
      trace_desc_compression_risk <= '0;
      trace_desc_spill_cost <= '0;
      trace_desc_service_criticality <= '0;
      trace_desc_policy_select_s5 <= 1'b1;
      trace_desc_temporal_persist_class <= '0;
      trace_desc_reuse_distance_class <= '0;
      trace_desc_query_structure_class <= '0;
      trace_desc_sched_urgency_hint <= '0;
      trace_desc_sig_valid <= 1'b0;
      trace_desc_query_sig <= 6'd0;
      trace_desc_key_sig <= 6'd0;
      trace_desc_prefix_class <= 2'd0;
      trace_desc_router_class <= 2'd0;
      trace_desc_wvalid <= 1'b0;
      trace_desc_wdata <= '0;

      for (beat_idx = 0; beat_idx < len_i; beat_idx = beat_idx + 1) begin
        addr_l = base_addr_i + ADDR_W'(beat_idx);
        if (op_i == KCMU_OP_WR) begin
          if (desc_payload_cursor >= desc_payload_count) begin
            $fatal(1, "%s descriptor payload underflow at beat=%0d", workload_name, beat_idx);
          end
          exp_data_l = desc_payload_mem[desc_payload_cursor];
          desc_payload_cursor = desc_payload_cursor + 1;
          @(negedge clk);
          trace_desc_wvalid <= 1'b1;
          trace_desc_wdata <= exp_data_l;
          wait_cnt = 0;
          while (!trace_desc_wready) begin
            @(posedge clk);
            wait_cnt = wait_cnt + 1;
            if (wait_cnt > READY_TIMEOUT) begin
              $fatal(1, "trace_desc_wready timeout beat=%0d base=%0d len=%0d", beat_idx, base_addr_i, len_i);
            end
          end
          @(negedge clk);
          trace_desc_wvalid <= 1'b0;
          trace_desc_wdata <= '0;
        end

        read_tier_l = LAT_TIER_NONE;
        l1_hit_before_l = dut.u_mcu.u_ex.stat_l1_hit_cnt;
        l2_demand_hit_before_l = dut.u_mcu.stat_l2_demand_hit_cnt;
        l2_demand_miss_before_l = dut.u_mcu.stat_l2_demand_miss_cnt;
        l2_vb_hit_before_l = dut.u_mcu.u_l2.stat_l2_vb_read_hit_cnt;
        l2_gf_hit_before_l = dut.u_mcu.u_l2.stat_l2_group_fetch_useful_cnt;
        wait_cnt = 0;
        while (!resp_valid) begin
          @(posedge clk);
          wait_cnt = wait_cnt + 1;
          if (wait_cnt > RESP_TIMEOUT) begin
            $fatal(1, "descriptor resp timeout beat=%0d base=%0d len=%0d", beat_idx, base_addr_i, len_i);
          end
        end

        lat_l = wait_cnt;
        last_resp_approx = resp_approx;

        if (op_i == KCMU_OP_RD) begin
          read_tier_l = classify_read_tier(
            resp_hit,
            l1_hit_before_l,
            l2_demand_hit_before_l,
            l2_demand_miss_before_l,
            l2_vb_hit_before_l,
            l2_gf_hit_before_l
          );
          exp_data_l = golden_mem[addr_l];
`ifdef KCMU_V409_DEBUG
          if ((addr_l >= ADDR_W'(48)) && (addr_l <= ADDR_W'(120))) begin
            $display("V409_TB_DESC beat=%0d addr=%0d exp=%h got=%h hit=%0d approx=%0d wait=%0d time=%0t",
                     beat_idx,
                     addr_l,
                     exp_data_l,
                     resp_rdata,
                     resp_hit,
                     resp_approx,
                     lat_l,
                     $time);
          end
`endif
          if (!read_value_match(exp_data_l, resp_rdata, resp_approx)) begin
            $fatal(1, "%s descriptor read mismatch beat=%0d addr=%0d exp=%h got=%h approx=%0d",
                   workload_name, beat_idx, addr_l, exp_data_l, resp_rdata, resp_approx);
          end
          record_access(KCMU_OP_RD, resp_hit, lat_l, read_tier_l);
        end else if (op_i == KCMU_OP_WR) begin
          if (resp_rdata !== {DATA_W{1'b0}}) begin
            $fatal(1, "%s descriptor write response must be zero", workload_name);
          end
          golden_mem[addr_l] = exp_data_l;
          record_access(KCMU_OP_WR, resp_hit, lat_l, LAT_TIER_NONE);
        end else begin
          $fatal(1, "descriptor workload only supports RD/WR ops");
        end

        @(posedge clk);
        while (resp_valid) begin
          @(posedge clk);
        end
      end
    end
  endtask

  function automatic integer sem_store_find_idx(
    input logic [ADDR_W-1:0] addr_i,
    input logic [KCMU_SEQ_W-1:0] seq_id_i,
    input kcmu_kv_kind_t kv_kind_i,
    input logic [2:0] layer_i,
    input logic [1:0] head_i,
    input logic [11:0] token_i
  );
    integer idx;
    begin
      sem_store_find_idx = -1;
      for (idx = 0; idx < sem_count; idx = idx + 1) begin
        if (sem_valid[idx] &&
            (sem_addr[idx] == addr_i) &&
            (sem_seq_id[idx] == seq_id_i) &&
            (sem_kv_kind[idx] == kv_kind_i) &&
            (sem_layer[idx] == layer_i) &&
            (sem_head[idx] == head_i) &&
            (sem_token[idx] == token_i)) begin
          sem_store_find_idx = idx;
          idx = sem_count;
        end
      end
    end
  endfunction

  task automatic sem_store_write(
    input logic [ADDR_W-1:0] addr_i,
    input logic [KCMU_SEQ_W-1:0] seq_id_i,
    input kcmu_kv_kind_t kv_kind_i,
    input logic [2:0] layer_i,
    input logic [1:0] head_i,
    input logic [11:0] token_i,
    input logic [DATA_W-1:0] data_i
  );
    integer idx;
    begin
      idx = sem_store_find_idx(addr_i, seq_id_i, kv_kind_i, layer_i, head_i, token_i);
      if (idx < 0) begin
        if (sem_count >= SEM_STORE_MAX) begin
          $fatal(1, "semantic store overflow");
        end
        idx = sem_count;
        sem_count = sem_count + 1;
      end
      sem_valid[idx] = 1'b1;
      sem_addr[idx] = addr_i;
      sem_seq_id[idx] = seq_id_i;
      sem_kv_kind[idx] = kv_kind_i;
      sem_layer[idx] = layer_i;
      sem_head[idx] = head_i;
      sem_token[idx] = token_i;
      sem_data[idx] = data_i;
    end
  endtask

  task automatic sem_store_reclaim_seq(input logic [KCMU_SEQ_W-1:0] seq_id_i);
    integer idx;
    begin
      for (idx = 0; idx < sem_count; idx = idx + 1) begin
        if (sem_valid[idx] && (sem_seq_id[idx] == seq_id_i)) begin
          sem_valid[idx] = 1'b0;
        end
      end
    end
  endtask

  task automatic get_expected_read_data(
    input logic meta_valid_i,
    input logic [ADDR_W-1:0] addr_i,
    input logic [KCMU_SEQ_W-1:0] seq_id_i,
    input kcmu_kv_kind_t kv_kind_i,
    input logic [2:0] layer_i,
    input logic [1:0] head_i,
    input logic [11:0] token_i,
    output logic [DATA_W-1:0] exp_data_o
  );
    integer idx;
    begin
      if (meta_valid_i) begin
        idx = sem_store_find_idx(addr_i, seq_id_i, kv_kind_i, layer_i, head_i, token_i);
        if (idx >= 0) exp_data_o = sem_data[idx];
        else          exp_data_o = golden_mem[addr_i];
      end else begin
        exp_data_o = golden_mem[addr_i];
      end
    end
  endtask

  task automatic reseed_backing_memory_identity();
    integer mi;
    begin
      for (mi = 0; mi < DEPTH; mi = mi + 1) begin
        golden_mem[mi] = 32'hA0000000 + mi;
        mem0.mem[mi] = golden_mem[mi];
      end
      for (mi = 0; mi < SEM_STORE_MAX; mi = mi + 1) begin
        sem_valid[mi] = 1'b0;
        sem_addr[mi] = '0;
        sem_seq_id[mi] = '0;
        sem_kv_kind[mi] = 1'b0;
        sem_layer[mi] = '0;
        sem_head[mi] = '0;
        sem_token[mi] = '0;
        sem_data[mi] = '0;
      end
      sem_count = 0;
    end
  endtask

  task automatic apply_workload_memory_seed(input string workload_name_i);
    integer mi;
    logic [31:0] seeded;
    begin
      if (workload_name_i == "cold_tail_compression") begin
        for (mi = 8'h58; mi < 8'h5D; mi = mi + 1) begin
          seeded = 32'h20202020;
          golden_mem[mi] = seeded;
          mem0.mem[mi] = seeded;
        end
        for (mi = 8'h68; mi < 8'h6D; mi = mi + 1) begin
          seeded = 32'h20202020;
          golden_mem[mi] = seeded;
          mem0.mem[mi] = seeded;
        end
        for (mi = 8'h70; mi < 8'h75; mi = mi + 1) begin
          seeded = 32'h20202020;
          golden_mem[mi] = seeded;
          mem0.mem[mi] = seeded;
        end
        for (mi = 8'h78; mi < 8'h7D; mi = mi + 1) begin
          seeded = 32'h20202020;
          golden_mem[mi] = seeded;
          mem0.mem[mi] = seeded;
        end
        for (mi = 8'h80; mi < 8'hE0; mi = mi + 1) begin
          seeded = 32'hB0000000 | (mi * 32'h00010001);
          golden_mem[mi] = seeded;
          mem0.mem[mi] = seeded;
        end
      end else if (workload_name_i == "prefill_only") begin
        for (mi = 8'h18; mi < 8'h28; mi = mi + 1) begin
          seeded = 32'h90000000 + (mi * 32'h00000101);
          golden_mem[mi] = seeded;
          mem0.mem[mi] = seeded;
        end
      end
    end
  endtask

  task automatic load_desc_payload_file(input string payload_path);
    integer fd;
    integer parsed;
    string line;
    logic [DATA_W-1:0] word_l;
    begin
      desc_payload_count = 0;
      desc_payload_cursor = 0;
      if (payload_path.len() != 0) begin
        fd = $fopen(payload_path, "r");
        if (fd == 0) begin
          $fatal(1, "failed to open descriptor payload file: %s", payload_path);
        end
        while (!$feof(fd)) begin
          line = "";
          parsed = $fgets(line, fd);
          if (line.len() == 0) begin
            continue;
          end
          if ((line.substr(0, 0) == "#") ||
              (line.substr(0, 0) == "\n") ||
              (line.substr(0, 0) == "\r")) begin
            continue;
          end
          parsed = $sscanf(line, "%h", word_l);
          if (parsed != 1) begin
            $fatal(1, "descriptor payload parse error: %s", line);
          end
          if (desc_payload_count >= DESC_PAYLOAD_MAX) begin
            $fatal(1, "descriptor payload file too large: count=%0d max=%0d", desc_payload_count, DESC_PAYLOAD_MAX);
          end
          desc_payload_mem[desc_payload_count] = word_l;
          desc_payload_count = desc_payload_count + 1;
        end
        $fclose(fd);
      end
    end
  endtask

  task automatic run_trace_file(input string trace_path);
    integer fd;
    integer parsed;
    integer op_i;
    integer len_i;
    integer attn_valid_i;
    integer recent_rank_i;
    integer token_block_i;
    integer attn_epoch_i;
    integer head_budget_i;
    integer query_rel_i;
    integer compression_risk_i;
    integer spill_cost_i;
    integer service_criticality_i;
    integer policy_select_s5_i;
    integer temporal_persist_i;
    integer reuse_distance_i;
    integer query_structure_i;
    integer sched_urgency_i;
    integer sig_valid_i;
    integer query_sig_i;
    integer key_sig_i;
    integer prefix_class_i;
    integer router_class_i;
    integer meta_i;
    integer seq_i;
    integer phase_i;
    integer kv_i;
    integer layer_i;
    integer head_i;
    integer prio_i;
    logic [SCORE_W-1:0] score_l;
    logic [SCORE_W-1:0] attn_score_l;
    logic [ADDR_W-1:0] base_addr_l;
    logic meta_valid_l;
    logic [KCMU_SEQ_W-1:0] seq_id_l;
    kcmu_phase_t phase_l;
    kcmu_kv_kind_t kv_kind_l;
    logic [2:0] layer_l;
    logic [1:0] head_l;
    logic [2:0] prio_l;
    logic [ADDR_W-1:0] addr_l;
    logic [DATA_W-1:0] wdata_l;
    logic [11:0] token_l;
    logic [DATA_W-1:0] rdata_l;
    logic [DATA_W-1:0] exp_data_l;
    logic hit_l;
    integer lat_l;
    integer tier_l;
    string line;
    begin
      fd = $fopen(trace_path, "r");
      if (fd == 0) begin
        $fatal(1, "failed to open trace file: %s", trace_path);
      end

      line_num = 0;
      while (!$feof(fd)) begin
        line = "";
        parsed = $fgets(line, fd);
        line_num = line_num + 1;
        if (line.len() == 0) begin
          continue;
        end
        if ((line.substr(0, 0) == "#") ||
            (line.substr(0, 0) == "\n") ||
            (line.substr(0, 0) == "\r")) begin
          continue;
        end

        if (trace_mode == "descriptor") begin
          service_criticality_i = 0;
          policy_select_s5_i = 1;
          temporal_persist_i = 0;
          reuse_distance_i = 0;
          query_structure_i = 0;
          sched_urgency_i = 0;
          sig_valid_i = 0;
          query_sig_i = 0;
          key_sig_i = 0;
          prefix_class_i = 0;
          router_class_i = 0;
          parsed = $sscanf(
            line,
            "%d %h %d %h %d %d %d %d %h %d %h %d %d %h %d %d %h %d %d %d %d %d %d %h %h %d %d",
            op_i,
            base_addr_l,
            len_i,
            score_l,
            seq_i,
            phase_i,
            kv_i,
            attn_valid_i,
            attn_score_l,
            recent_rank_i,
            token_block_i,
            attn_epoch_i,
            head_budget_i,
            query_rel_i,
            compression_risk_i,
            spill_cost_i,
            service_criticality_i,
            policy_select_s5_i,
            temporal_persist_i,
            reuse_distance_i,
            query_structure_i,
            sched_urgency_i,
            sig_valid_i,
            query_sig_i,
            key_sig_i,
            prefix_class_i,
            router_class_i
          );
          if (parsed != 27 && parsed != 22 && parsed != 18 && parsed != 17 && parsed != 16) begin
            attn_valid_i = 0;
            attn_score_l = '0;
            recent_rank_i = 0;
            token_block_i = 0;
            attn_epoch_i = 0;
            head_budget_i = 0;
            query_rel_i = 0;
            compression_risk_i = 0;
            spill_cost_i = 0;
            service_criticality_i = 0;
            policy_select_s5_i = 1;
            temporal_persist_i = 0;
            reuse_distance_i = 0;
            query_structure_i = 0;
            sched_urgency_i = 0;
            sig_valid_i = 0;
            query_sig_i = 0;
            key_sig_i = 0;
            prefix_class_i = 0;
            router_class_i = 0;
            parsed = $sscanf(
              line,
              "%d %h %d %h %d %d %d %d %h %d %h %d",
              op_i,
              base_addr_l,
              len_i,
              score_l,
              seq_i,
              phase_i,
              kv_i,
              attn_valid_i,
              attn_score_l,
              recent_rank_i,
              token_block_i,
              attn_epoch_i
            );
          end
          if (parsed != 27 && parsed != 22 && parsed != 18 && parsed != 17 && parsed != 16 && parsed != 12) begin
            attn_valid_i = 0;
            attn_score_l = '0;
            recent_rank_i = 0;
            token_block_i = 0;
            attn_epoch_i = 0;
            head_budget_i = 0;
            query_rel_i = 0;
            compression_risk_i = 0;
            spill_cost_i = 0;
            service_criticality_i = 0;
            policy_select_s5_i = 1;
            temporal_persist_i = 0;
            reuse_distance_i = 0;
            query_structure_i = 0;
            sched_urgency_i = 0;
            sig_valid_i = 0;
            query_sig_i = 0;
            key_sig_i = 0;
            prefix_class_i = 0;
            router_class_i = 0;
            parsed = $sscanf(
              line,
              "%d %h %d %h %d %d %d",
              op_i,
              base_addr_l,
              len_i,
              score_l,
              seq_i,
              phase_i,
              kv_i
            );
          end
          if (parsed != 7 && parsed != 12 && parsed != 16 && parsed != 17 && parsed != 18 && parsed != 22 && parsed != 27) begin
            $fatal(1, "descriptor trace parse error at line %0d: %s", line_num, line);
          end
          seq_id_l = seq_i[KCMU_SEQ_W-1:0];
          phase_l = kcmu_phase_t'(phase_i[0]);
          kv_kind_l = kcmu_kv_kind_t'(kv_i[0]);
          desc_head_budget_class_cfg = head_budget_i[KCMU_HEAD_BUDGET_W-1:0];
          desc_query_relevance_cfg = query_rel_i[SCORE_W-1:0];
          desc_compression_risk_cfg = compression_risk_i[KCMU_COST_CLASS_W-1:0];
          desc_spill_cost_cfg = spill_cost_i[KCMU_COST_CLASS_W-1:0];
          desc_service_criticality_cfg = service_criticality_i[SCORE_W-1:0];
          desc_policy_select_s5_cfg = policy_select_s5_i[0];
          desc_temporal_persist_class_cfg = temporal_persist_i[KCMU_DESC_CLASS_W-1:0];
          desc_reuse_distance_class_cfg = reuse_distance_i[KCMU_DESC_CLASS_W-1:0];
          desc_query_structure_class_cfg = query_structure_i[KCMU_DESC_CLASS_W-1:0];
          desc_sched_urgency_hint_cfg = sched_urgency_i[KCMU_SCHED_HINT_W-1:0];
          desc_sig_valid_cfg = sig_valid_i[0];
          desc_query_sig_cfg = query_sig_i[5:0];
          desc_key_sig_cfg = key_sig_i[5:0];
          desc_prefix_class_cfg = prefix_class_i[1:0];
          desc_router_class_cfg = router_class_i[1:0];
          do_descriptor(
            kcmu_op_t'(op_i[1:0]),
            base_addr_l,
            len_i[7:0],
            score_l,
            seq_id_l,
            phase_l,
            kv_kind_l,
            attn_valid_i[0],
            attn_score_l,
            recent_rank_i[KCMU_ATTN_RANK_W-1:0],
            token_block_i[KCMU_TOKEN_BLOCK_W-1:0],
            attn_epoch_i[KCMU_ATTN_EPOCH_W-1:0]
          );
          desc_head_budget_class_cfg = '0;
          desc_query_relevance_cfg = '0;
          desc_compression_risk_cfg = '0;
          desc_spill_cost_cfg = '0;
          desc_service_criticality_cfg = '0;
          desc_policy_select_s5_cfg = 1'b1;
          desc_temporal_persist_class_cfg = '0;
          desc_reuse_distance_class_cfg = '0;
          desc_query_structure_class_cfg = '0;
          desc_sched_urgency_hint_cfg = '0;
          desc_sig_valid_cfg = 1'b0;
          desc_query_sig_cfg = 6'd0;
          desc_key_sig_cfg = 6'd0;
          desc_prefix_class_cfg = 2'd0;
          desc_router_class_cfg = 2'd0;
        end else begin
          parsed = $sscanf(
            line,
            "%d %h %h %d %d %d %d %d %d %h %d",
            op_i,
            addr_l,
            wdata_l,
            meta_i,
            seq_i,
            phase_i,
            kv_i,
            layer_i,
            head_i,
            token_l,
            prio_i
          );
          if (parsed != 11) begin
            $fatal(1, "trace parse error at line %0d: %s", line_num, line);
          end

          meta_valid_l = meta_i[0];
          seq_id_l = seq_i[KCMU_SEQ_W-1:0];
          phase_l = kcmu_phase_t'(phase_i[0]);
          kv_kind_l = kcmu_kv_kind_t'(kv_i[0]);
          layer_l = layer_i[2:0];
          head_l = head_i[1:0];
          prio_l = prio_i[2:0];

          do_cmd_with_full_meta(
            kcmu_op_t'(op_i[1:0]),
            addr_l,
            wdata_l,
            meta_valid_l,
            seq_id_l,
            phase_l,
            kv_kind_l,
            layer_l,
            head_l,
            token_l,
            prio_l,
            rdata_l,
            hit_l,
            lat_l,
            tier_l
          );

          case (op_i)
            KCMU_OP_RD: begin
              get_expected_read_data(
                meta_valid_l,
                addr_l,
                seq_id_l,
                kv_kind_l,
                layer_l,
                head_l,
                token_l,
                exp_data_l
              );
              if (!read_value_match(exp_data_l, rdata_l, last_resp_approx)) begin
                $fatal(
                  1,
                  "%s read mismatch at line %0d addr=%0d exp=%h got=%h approx=%0d meta=%0d seq=%0d tok=%0d",
                  workload_name,
                  line_num,
                  addr_l,
                  exp_data_l,
                  rdata_l,
                  last_resp_approx,
                  meta_i,
                  seq_i,
                  token_l
                );
              end
              record_access(KCMU_OP_RD, hit_l, lat_l, tier_l);
            end

            KCMU_OP_WR: begin
              if (rdata_l !== {DATA_W{1'b0}}) begin
                $fatal(1, "%s write response must be zero at line %0d", workload_name, line_num);
              end
              if (meta_i != 0) begin
                sem_store_write(
                  addr_l,
                  seq_id_l,
                  kv_kind_l,
                  layer_l,
                  head_l,
                  token_l,
                  wdata_l
                );
              end else begin
                golden_mem[addr_l] = wdata_l;
              end
              record_access(KCMU_OP_WR, hit_l, lat_l, LAT_TIER_NONE);
            end

            KCMU_OP_NOP: begin
              if (meta_i != 0) begin
                sem_store_reclaim_seq(seq_id_l);
              end
            end

            default: begin
              $fatal(1, "unsupported opcode at line %0d: %0d", line_num, op_i);
            end
          endcase
        end
      end
      $fclose(fd);
    end
  endtask

