    total_backend_demand_bridge_hh_reads = 0;
    total_backend_demand_bridge_query_reads = 0;
    last_resp_approx = 1'b0;

    if (!$value$plusargs("TRACE_FILE=%s", trace_file)) begin
      $fatal(1, "TRACE_FILE plusarg is required");
    end
    if (!$value$plusargs("WORKLOAD_NAME=%s", workload_name)) begin
      workload_name = "unnamed_workload";
    end
    if (!$value$plusargs("TRACE_MODE=%s", trace_mode)) begin
      trace_mode = "legacy";
    end
    if (!$value$plusargs("DESC_PAYLOAD_FILE=%s", desc_payload_file)) begin
      desc_payload_file = "";
    end
    if (!$value$plusargs("PREFETCH_ENABLE=%d", pf_enable_arg)) begin
      pf_enable_arg = 1;
    end
    if (!$value$plusargs("V630_EXTRA_CVR_HINT=%d", v630_extra_cvr_hint_arg)) begin
      v630_extra_cvr_hint_arg = 0;
    end
    if (!$value$plusargs("BACKEND_SERVICE_CYCLES=%d", backend_service_cycles_arg)) begin
      backend_service_cycles_arg = HBM_IF_SERVICE_CYCLES;
    end
    if (backend_service_cycles_arg != HBM_IF_SERVICE_CYCLES) begin
      $fatal(1,
             "BACKEND_SERVICE_CYCLES plusarg (%0d) does not match compiled KCMU_TB_HBM_IF_SERVICE_CYCLES (%0d)",
             backend_service_cycles_arg,
             HBM_IF_SERVICE_CYCLES);
    end
    if (!$value$plusargs("MEM_READ_LATENCY=%d", mem_read_latency_arg)) begin
      mem_read_latency_arg = MEM_RD_LATENCY;
    end
    if (mem_read_latency_arg != MEM_RD_LATENCY) begin
      $fatal(1,
             "MEM_READ_LATENCY plusarg (%0d) does not match compiled KCMU_TB_MEM_RD_LATENCY (%0d)",
             mem_read_latency_arg,
             MEM_RD_LATENCY);
    end
    prefetch_enable = (pf_enable_arg != 0);

    reseed_backing_memory_identity();
    apply_workload_memory_seed(workload_name);
    load_desc_payload_file(desc_payload_file);
    apply_reset(5);

    $display("SYS_EVAL_START: config=%s workload=%s trace_mode=%s trace_file=%s prefetch_enable=%0d",
             CONFIG_NAME, workload_name, trace_mode, trace_file, prefetch_enable);

    trace_start_cycle = sim_cycle_counter;
    run_trace_file(trace_file);
    trace_end_cycle = sim_cycle_counter;
    trace_wall_cycles = trace_end_cycle - trace_start_cycle;
    if (trace_wall_cycles <= 0) begin
      trace_wall_cycles = 1;
    end

    $display("SYS_SUMMARY: ops=%0d reads=%0d writes=%0d hits=%0d misses=%0d avg_lat=%0f max_lat=%0d",
